        name = "Land Shark",
        warlordsPetGuide = true,
        sourceType = "Vendor",
        stepCount = 5,
        acquisition = "Difficulty: Hard - Fishing Shack unlocks, Nat recruitment and fifty lunker/coin rewards require sustained fishing from scratch.\n\n1. Open the Fishing Shack, then work toward Draenor Angler by catching the required enormous fish in Draenor's six main zones. Train Draenor Fishing and use fishing equipment/lures. Buy and construct the level 3 Shack blueprint when unlocked.\n\n2. Take Luring Nat from the Shack NPC, catch its special fish, then complete Finding Nat Pagle at Anglers Wharf in Krasarang Wilds. Accept The Great Angler Returns BEFORE leaving Nat and return to your Garrison. Finish A True Draenor Angler's six special lunkers and An Angler on Our Team to recruit him.\n\n3. Assign Nat to the Fishing Shack, fish ordinary Draenor lunkers in the appropriate zones and turn them in to him. These hand-ins award Nat's Lucky Coins and friendship. The ordinary repeatable lunkers are different from his recruitment-quest fish. Save fifty coins.\n\n4. Continue turning in lunkers until Nat's friendship reaches Good Friend as well as having fifty coins. Buy Land Shark from Nat at your Garrison Fishing Shack and learn it; a generic Anglers reputation rank is not his personal friendship rank.\n\n5. If you do not want the recruitment and fishing grind, buy the exact Land Shark item/cage from a player. Do not copy fixed gold prices from old comments; prices depend on the current market.",
