        npcId = 77221,
        petNPCID = 77221,
        name = "Iron Starlette",
        warlordsPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 5,
        acquisition = "Difficulty: Easy - A short legacy combat chain; choosing the correct zone phase is the main complication.\n\n1. Enable trivial-quest tracking and travel to PRESENT-DAY Blasted Lands. If you see the pre-invasion landscape, speak to Zidormi by the northern border to restore the present. The WoD Dark Portal introduction can hide these quests while active: finish or abandon that conflicting introduction before looking again.\n\n2. Alliance: meet Vindicator Maraad at Shattered Beachhead 66.6,28.2. Horde: meet Thrall at Shattered Landing 71.8,47.7. Accept Attack of the Iron Horde and Under Siege, kill the required Ironmarch Grunts and sabotage three demolishers.\n\n3. Complete Subversive Scouts and Ending Executions, then Investigating the Invasion. Follow Maraad/Thrall to the forward camp, collect the lieutenants' three battleplans, plant your faction's flags in Nethergarde and recover the three named mementos/supplies. The tracked route handles each faction's quest IDs separately.\n\n4. Complete the Dreadmaul ogre kills, Toothsmash the Annihilator and the three poisoned cooking pots. Finish Gar'mak Bladetwist at Okril'lon Hold, then accept Report to the King (Alliance) or Warning Orgrimmar (Horde). Return to the capital NPC shown by the live quest rather than assuming an old faction-leader phase.\n\n5. Hand in the final quest and use the Iron Starlette reward. If a later expansion's capital phasing hides the turn-in, keep the quest and resolve that capital's active story phase or use an unfinished alt. An Auction House item/cage bypasses the chain.",
