        commentIDs = { 2079852, 2121947, 3183207, 6021308, 6271615 },
        tips = "Older comments refer to the original +100 / +125 stat foods; those values changed with scaling. Identify the named recipe instead. Basic Grilled Saberfish is not the recommended farm, and a Chef's Hat speeds cooking rather than raising the pet's drop chance.",
