        npcId = 78895,
        petNPCID = 78895,
        name = "Lil' Leftovers",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Eligible cooking has a low random proc chance and can consume thousands of ingredients; a cage is the direct alternative.\n\n1. Learn Draenor Cooking and choose a confirmed recipe such as Sleeper Surprise, Calamari Crepes, Gorgrond Chowder, Sleeper Sushi or Pickled Eel. Compare ingredient prices with an already-caged Lil' Leftovers before committing to a long farm.\n\n2. For a simple one-recipe route, obtain Sleeper Sushi and stock Fat Sleeper Flesh and Crescent Saberfish Flesh. Fish the ingredients, buy them, or check the Garrison Trading Post's current material stock. Keep bag space for the cooked food and pet.\n\n3. Cook the qualifying dish repeatedly at a cooking fire. Lil' Leftovers can appear directly in your bags as an additional result. The later Draenor fish recipes and feasts also qualify; neither making only feasts nor changing your character's combat stats guarantees a proc.\n\n4. Check bags after each cooking session and learn the pet item when it appears. Stop when the ingredient/time cost exceeds what you want to spend; a cage is an available alternative. Failed batches do not establish that the pet has been removed or that the next batch is guaranteed.",
