        npcId = 79039,
        petNPCID = 79039,
        name = "Crazy Carrot",
        warlordsPetGuide = true,
        sourceType = "Vendor",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Collecting one thousand seeds takes repeated gardening or outdoor Herbalism.\n\n1. Unlock the Herb Garden at your level 2 Garrison using Clearing the Garden. Speak to Naron Bloomthistle in Lunarfall or Tarnon in Frostwall. Check his vendor stock for Crazy Carrot before spending resources on an unnecessary upgrade.\n\n2. Collect Draenic Seeds from harvesting Draenor herbs. Characters without Herbalism can harvest their Garrison garden on each daily reset; herbalists can gather outdoor nodes as well. Garden upgrades increase the number of available herbs and speed accumulation.\n\n3. Save one thousand seeds on the purchasing character, then buy Crazy Carrot from the garden vendor and use the item. Seeds used to buy something else cannot also pay for the pet.\n\n4. Alternatively buy the exact Crazy Carrot cage on the Auction House. It is cageable, so non-herbalists can skip the seed grind without changing professions.",
