        commentIDs = { 1970515 },
        tips = "Use Draenor Engineering's current skill panel. Launch-era '700 Engineering' refers to the old combined skill system. Engineering is not required to learn the pet. The Garrison map marks the hub because small-building plots can be rearranged.",
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - your building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - your building plot varies" },
        },
        npcId = 79410,
        petNPCID = 79410,
        name = "Mechanical Axebeak",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - The craft is simple, but schematics and soulbound Gearspring Parts require profession cooldowns or building work orders.\n\n1. If you only want the pet, compare the Auction House price for Mechanical Axebeak before building an entire workshop. Buying the correct pet or cage bypasses its crafting requirements.\n\n2. For an engineer, train Draenor Engineering and make a Secret of Draenor Engineering with the profession's daily recipe. Buy this pet's schematic from Zaren Hoffle in Lunarfall, Pozzlow in Frostwall, or the Engineering Plans vendor in your Ashran faction hub, then learn it.\n\n3. Produce Gearspring Parts with the Draenor Engineering recipe and/or Engineering Works work orders. Parts are soulbound: buying ordinary ore does not let a different character spend your parts. Save 50 Gearspring Parts on the character doing the craft.\n\n4. Without Engineering, upgrade your own Engineering Works to level 3 and use its crafting NPC's pet service. Complete 250 Garrison work orders for Working More Orders (9406) if its blueprint is locked, buy/build the upgrade, and collect the parts from work orders before requesting this pet.\n\n5. For a personal craft have the required Arclight Spanner or an equivalent engineering multitool available, then craft Mechanical Axebeak. Alternatively collect the NPC's crafted item. Use the learning item to add the pet. Each extra copy consumes another full set of materials.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=79410",
    },
