        npcId = 80101,
        petNPCID = 80101,
        name = "Royal Peachick",
        warlordsPetGuide = true,
        sourceType = "Achievements",
        stepCount = 6,
        acquisition = "Difficulty: Hard - A six-zone capture checklist includes scarce primaries such as Crimsonwing Moth and Sapphire Firefly.\n\n1. Track Draenor Safari (9685) in the achievement window and prepare level-25 pets with a safe capture attack. Only the species actually listed in the achievement are mandatory; buying a similar pet or catching a different species does not tick a missing criterion.\n\n2. Start in Frostfire Ridge with the rats, wasps, larvae and the primary-only Frostshell Pincher / Ironclaw Scuttler. Use Wor'gol 23,64 for the Pincher and the snowy slopes east of Bladespire around 33.7,41.4 for the Scuttler.\n\n3. In Shadowmoon Valley work the Moonshell Crabs on Moonlit Shore and check their backlines for Zangar Crawler / Mossbite Skitterer. In Gorgrond search the southern jungle for birds/wasps and the Fertile Ground 41,77 for Mudback Calf.\n\n4. Sweep Talador for its common species and check the special areas for Shadow Sporebat in Zangarra and Flat-Tooth Calf by Duskfall Lake. Patrol the separate Crimsonwing Moth locations; take any quality instead of waiting for a rare.\n\n5. In Spires of Arak collect the common coast/woodland species and patrol the Sapphire Firefly spawn sites, including 55.4,32.4 and 59,68.6. Finish Nagrand's primary Leatherhide Runt around clefthoof herds or the Hallvalor hut 85,55. Use each species' individual guide for the full route.\n\n6. Review the achievement's unchecked names and capture those exact species, winning the full battle after trapping each. On completion claim the Royal Peacock reward item from achievement mail and learn Royal Peachick. The reward item's older Peacock name is intentional.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=80101",
