        difficulty = "medium",
        difficultyReason = "The craft is simple, but schematics and soulbound Gearspring Parts require profession cooldowns or building work orders.",
        requirements = "Draenor Engineering and the schematic, OR a level 3 Engineering Works",
        cost = "50 Gearspring Parts and 40 Sumptuous Fur; engineer's schematic costs 1 Secret of Draenor Engineering",
        references = {
            "https://www.wowhead.com/spell=162210",
            "https://www.wowhead.com/npc=80329",
            "https://www.wowhead.com/item=112057",
            "https://www.wowhead.com/npc=80329#comments:id=2037512",
        },
        commentIDs = { 2037512 },
        tips = "Use Draenor Engineering's current skill panel. Launch-era '700 Engineering' refers to the old combined skill system. Engineering is not required to learn the pet. The Garrison map marks the hub because small-building plots can be rearranged.",
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - your building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - your building plot varies" },
        },
        npcId = 80329,
        petNPCID = 80329,
        name = "Lifelike Mechanical Frostboar",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - The craft is simple, but schematics and soulbound Gearspring Parts require profession cooldowns or building work orders.\n\n1. If you only want the pet, compare the Auction House price for Lifelike Mechanical Frostboar before building an entire workshop. Buying the correct pet or cage bypasses its crafting requirements.\n\n2. For an engineer, train Draenor Engineering and make a Secret of Draenor Engineering with the profession's daily recipe. Buy this pet's schematic from Zaren Hoffle in Lunarfall, Pozzlow in Frostwall, or the Engineering Plans vendor in your Ashran faction hub, then learn it.\n\n3. Produce Gearspring Parts with the Draenor Engineering recipe and/or Engineering Works work orders. Parts are soulbound: buying ordinary ore does not let a different character spend your parts. Save 50 Gearspring Parts and 40 Sumptuous Fur on the character doing the craft.\n\n4. Without Engineering, upgrade your own Engineering Works to level 3 and use its crafting NPC's pet service. Complete 250 Garrison work orders for Working More Orders (9406) if its blueprint is locked, buy/build the upgrade, and collect the parts from work orders before requesting this pet.\n\n5. For a personal craft have the required Gyromatic Micro-Adjustor or an equivalent engineering multitool available, then craft Lifelike Mechanical Frostboar. Alternatively collect the NPC's crafted item. Use the learning item to add the pet. Each extra copy consumes another full set of materials.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=80329",
    },
    [1416] = {
        category = "Treasure",
        source = "Teroclaw Nest - Talador",
        description = "Loot a clickable nest, not a dead Teroclaw or a wild pet battle.",
        difficulty = "easy",
        difficultyReason = "A short trip to an outdoor nest; one learning item per character.",
        requirements = "A character that has not already looted its nest reward, or a pet cage",
        cost = "No currency",
        commentIDs = { 1984614, 2034485, 2063010, 2360717, 2872205 },
        waypoints = {
            { mapID = 535, x = 0.72, y = 0.37, step = 1, label = "Vol'jin's Pride - nesting area" },
            { mapID = 535, x = 0.71, y = 0.32, step = 2, label = "Alternative nest north of the outpost" },
            { mapID = 535, x = 0.5475, y = 0.5245000000000001, step = 2, label = "Alternative nests near Tomb of Lights" },
        },
        npcId = 81431,
        petNPCID = 81431,
        name = "Teroclaw Hatchling",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short trip to an outdoor nest; one learning item per character.\n\n1. Travel to Talador in Draenor and search the nesting birds southeast of Vol'jin's Pride around 72,37. Bring bag space; there is no combat-pet level requirement for looting the treasure.\n\n2. Click a Teroclaw Nest on the ground among the chicks. Nearby nest locations include 71,32 and 54.75,52.45 northwest of the Tomb of Lights. You are looking for an interactable nest, not an ordinary egg decoration.\n\n3. Loot and use the hatchling item. The treasure's pet reward is once per character; an empty nest window on a character that already took it does not mean the species has been removed.\n\n4. For another copy use an unfinished character or buy the Teroclaw Hatchling cage. Older battle advice that combines Dodge and Nature's Ward predates their placement in the same ability slot.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=81431",
        references = {
            "https://www.wowhead.com/npc=81431",
