            "https://www.wowhead.com/npc=81431#comments:id=2872205",
        },
    },
    [1426] = {
        category = "Professions",
        source = "Draenor Tailoring",
        itemId = 113216,
        description = "A tailor makes the plushie; a Tailoring Emporium alone cannot craft it for a non-tailor.",
        difficulty = "medium",
        difficultyReason = "Five daily recipe tokens and fifty Hexweave Cloth can gate a fresh tailor; a cage bypasses the craft.",
        requirements = "Draenor Tailoring for the personal craft",
        cost = "5 Secrets of Draenor Tailoring for the pattern; 50 Hexweave Cloth and 10 Sorcerous Earth per pet",
        commentIDs = { 2172437 },
        references = {
            "https://www.wowhead.com/spell=168849",
            "https://www.wowhead.com/item=114865",
            "https://www.wowhead.com/npc=82464",
            "https://www.wowhead.com/item=113216",
            "https://www.wowhead.com/npc=82464#comments:id=2172437",
        },
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - your building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - your building plot varies" },
        },
        npcId = 82464,
        petNPCID = 82464,
        name = "Elekk Plushie",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Five daily recipe tokens and fifty Hexweave Cloth can gate a fresh tailor; a cage bypasses the craft.\n\n1. Choose a tailor with Draenor Tailoring, or buy an Elekk Plushie cage. The crafted item is soulbound; another tailor must learn and cage the pet before trading it to you.\n\n2. Make Secrets of Draenor Tailoring on five available daily cooldowns and spend five secrets on Pattern: Elekk Plushie at your tailoring recipe vendor. The Emporium or your Ashran faction hub sells the pattern; learn it on the tailor.\n\n3. Gather fifty Hexweave Cloth and ten Sorcerous Earth. Produce cloth through the tailor's Draenor cooldown and Emporium work orders, or obtain the materials through the Auction House. An Emporium supplies cloth but does not replace Tailoring for this pet craft.\n\n4. Craft and learn the plushie, or learn the purchased cage. It is intentionally unable to deal damage. Taking it through An Awfully Big Adventure earns Trunks; that achievement is a separate objective and is not required to collect this plushie.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=82464",
    },
    [1427] = {
        category = "Pet Battles",
        source = "Wild capture - Coldsnap Bluffs, Frostfire Ridge",
        description = "Capture Frostfur Rat in a wild pet battle. Search the documented habitat for a green paw, rather than attacking ordinary critters with character abilities.",
        difficulty = "easy",
        difficultyReason = "A normal level-23 to level-25 wild capture with a prepared team.",
        requirements = "Battle Pet Training, a usable trap and a healthy team suited to Draenor's level-23 to level-25 wild pets",
        cost = "No currency; these wild captures cannot be caged",
        commentIDs = { 2039230, 6147456 },
        tips = "Take any quality for collection credit and upgrade it with a battle-stone later. Clear nearby hostile creatures before starting, stand on unobstructed ground and heal between attempts. Old random-group realm hopping is not a reliable Retail method.",
        waypoints = {
            { mapID = 525, x = 0.54, y = 0.20199999999999999, step = 2, label = "Coldsnap Bluffs - rats and wasp backlines" },
        },
        npcId = 82715,
        petNPCID = 82715,
        name = "Frostfur Rat",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A normal level-23 to level-25 wild capture with a prepared team.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to Coldsnap Bluffs, Frostfire Ridge. Search around 54.0,20.2 and the Bloodmaul Slag Mines approach. Rats also accompany Twilight Wasps and other Frostfire pets, so inspect secondary slots instead of waiting for a rare primary.\n\n3. Engage the green-paw pet and check the enemy names. If Frostfur Rat is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Frostfur Rat below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=82715",
        references = {
            "https://www.wowhead.com/npc=82715",
            "https://www.wowhead.com/npc=82715#comments:id=2039230",
            "https://www.wowhead.com/npc=82715#comments:id=6147456",
        },
    },
    [1428] = {
        category = "Drop",
        source = "Darktide Husks and Darktide Boneshells - southern Shadowmoon Valley",
        itemId = 113554,
        description = "Farm the undead crawlers around Darktide Roost; Zomstrok itself is the companion, not a rare boss to camp.",
        difficulty = "medium",
        difficultyReason = "A random ordinary-mob drop; modern character damage makes the combat simple.",
        requirements = "Access to Darktide Roost, or a cage",
        cost = "No currency",
        commentIDs = { 1979552, 2062670, 2095518, 2264231 },
        areaMaps = { 539 },
        npcId = 83562,
        petNPCID = 83562,
        name = "Zomstrok",
        warlordsPetGuide = true,
        sourceType = "Drop",
        stepCount = 4,
        acquisition = "Difficulty: Medium - A random ordinary-mob drop; modern character damage makes the combat simple.\n\n1. Travel to Darktide Roost on the southern islands of Draenor Shadowmoon Valley. Search the shoreline and small islands for Darktide Husks / Darktide Boneshells, the undead bogstrok-like crawlers.\n\n2. Kill and loot these crawlers while making a circuit of the coast. The older name Soulless Darktide Oracle was replaced; do not search for a modern rare named Zomstrok.\n\n3. Continue around the islands while the previous groups respawn. Hallow's End's Bonefleet quest phase can replace some of the normal targets, so use unaffected shoreline or return outside that phase rather than assuming the pet is retired.\n\n4. Use the Zomstrok item when it drops. There is no guaranteed kill count; compare its caged price if the farm is taking longer than you want.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=83562",
        references = {
            "https://www.wowhead.com/npc=83562",
            "https://www.wowhead.com/item=113554",
            "https://www.wowhead.com/npc=83562#comments:id=1979552",
            "https://www.wowhead.com/npc=83562#comments:id=2062670",
            "https://www.wowhead.com/npc=83562#comments:id=2095518",
            "https://www.wowhead.com/npc=83562#comments:id=2264231",
        },
    },
    [1430] = {
        category = "Reputation",
        source = "Steamwheedle Preservation Society - Revered",
        itemId = 119149,
        description = "Earn the named reputation on the purchasing character, save the Apexis/gold price, then buy the companion.",
        difficulty = "medium",
        difficultyReason = "Simple legacy combat, but reputation and currency collection require a sustained route.",
        requirements = "Steamwheedle Preservation Society - Revered",
        cost = "2,000 Apexis Crystals plus 1,000 gold base price, reduced by applicable reputation discounts",
        commentIDs = { 2063249 },
        tips = "A learned pet cage bypasses the vendor's reputation and purchasing-faction requirements. Draenor Timewalking commendations, when available from the current event vendor, can supplement the grind; check the actual faction token rather than buying a similarly named Outland token.",
        waypoints = {
            {
                mapID = 550,
                x = 0.502,
                y = 0.41200000000000003,
                step = 2,
                label = "Preservation Society - relic/fragment hand-ins",
            },
            { mapID = 550, x = 0.504, y = 0.414, step = 4, label = "Kwilax Fuseshiv - Forest Sproutling vendor" },
            { mapID = 550, x = 0.516, y = 0.162, step = 2, label = "Aogexon - reputation trophy chance" },
            { mapID = 550, x = 0.341, y = 0.515, step = 2, label = "Mu'gra - reputation trophy chance" },
            {
                mapID = 550,
                x = 0.37200000000000005,
                y = 0.38799999999999996,
                step = 2,
                label = "Vileclaw - reputation trophy chance",
            },
        },
        npcId = 83583,
        petNPCID = 83583,
        name = "Forest Sproutling",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use either faction and check its Steamwheedle Preservation Society reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. In northern Draenor Nagrand, kill eligible wildlife and open Highmaul Reliquary chests for Gorian Artifact Fragments and Highmaul Relics. At Ruins of Na'gwa 50.2,41.2, give Sallee Silverclamp twenty fragments for 250 base reputation or one relic for 350. Named beasts such as Aogexon, Mu'gra and Vileclaw drop separate trophy items for Gazmolf's 500-base-reputation hand-ins. Repeat until Revered.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Buy Captured Forest Sproutling from Kwilax Fuseshiv at Ruins of Na'gwa 50.4,41.4, or from Gazrix Gearlock in Stormshield / Mimi Wizzlebub in Warspear. The neutral camp is northwest across the river from Lok-rath; Ring of Trials is a different place.\n\n5. Use the purchased item to learn Forest Sproutling. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=83583",
        references = {
            "https://www.wowhead.com/npc=83583",
            "https://www.wowhead.com/item=119149",
            "https://www.wowhead.com/npc=83583#comments:id=2063249",
        },
    },
    [1432] = {
        category = "Professions",
        source = "Node-triggered Disturbed Podling - Draenor Herbalism",
        description = "Harvest outdoor nodes, then loot the specific mob spawned by gathering. This pet is not a direct result of every node.",
        difficulty = "hard",
        difficultyReason = "Two random events are needed: spawning the correct gathering mob and then receiving its uncommon pet drop.",
        requirements = "Herbalism for outdoor gathering, or a purchased pet cage",
        cost = "No vendor price; gathering time or player-set cage price",
        commentIDs = { 2030249 },
        areaMaps = { 539, 543, 535, 542, 550, 525 },
        npcId = 83594,
        petNPCID = 83594,
        name = "Nightshade Sproutling",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Two random events are needed: spawning the correct gathering mob and then receiving its uncommon pet drop.\n\n1. Train Herbalism on the character gathering in Draenor, enable its minimap tracking, and clear enough bag space for nodes and loot. A high-level character makes the spawned mob easier to defeat.\n\n2. Gather outdoor Draenor herb nodes with Herbalism. A Disturbed Podling can emerge from a node; kill and loot that spawned mob. Historical comments describe Garrison garden spawns, but later replies report that outdoor herbs are the dependable way to encounter the correct mob.\n\n3. Follow accessible herb nodes in Shadowmoon Valley or another Draenor zone, collecting each herb and watching for the attacking Podling. Ordinary podlings in camps do not replace the node-triggered source.\n\n4. When Disturbed Podling spawns, defeat it and loot the corpse. Learn Nightshade Sproutling if it drops; otherwise continue gathering new nodes. There is no guaranteed number of mobs, and buying the caged species avoids the random farm.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=83594",
        references = { "https://www.wowhead.com/npc=83594", "https://www.wowhead.com/npc=83594#comments:id=2030249" },
    },
    [1434] = {
        category = "Pet Battles",
        source = "Big Bag of Pet Supplies - level 3 Garrison Menagerie daily",
        itemId = 118598,
        description = "A random pet inside the level 3 Menagerie's daily reward bag; the unlock quest does not guarantee this species.",
        difficulty = "hard",
        difficultyReason = "A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.",
        requirements = "Level 3 Menagerie for the full daily bag, or a purchased cage",
        cost = "Garrison/building upgrades and time; no pet currency purchase",
        commentIDs = { 2075915 },
        references = {
            "https://www.wowhead.com/item=118697",
            "https://www.wowhead.com/quest=37644",
            "https://www.wowhead.com/quest=37645",
            "https://www.wowhead.com/npc=83588",
            "https://www.wowhead.com/item=118598",
            "https://www.wowhead.com/npc=83588#comments:id=2075915",
        },
        tips = "Albino Chimaeraling is not a Tamed Chimaera drop. Ghastly Kid is not guaranteed from beating Eleanor. Battle Pet Roundup / Scrappin' reward the Big Bag at Menagerie level 3; old journal wording may still call the source Mastering the Menagerie.",
        waypoints = {
            { mapID = 582, x = 0.28600000000000003, y = 0.392, step = 2, label = "Lio the Lioness - Menagerie" },
            { mapID = 590, x = 0.326, y = 0.42200000000000004, step = 2, label = "Serr'ah - Menagerie" },
        },
        npcId = 83588,
        petNPCID = 83588,
        name = "Sun Sproutling",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.\n\n1. Upgrade your Garrison to level 3 and learn Battle Pet Training. Accept Unearthed Magic from Lio the Lioness (Alliance) or Serr'ah (Horde), collect the Strange Stone near the mine entrance and return it. Its Ultimate Battle-Training Stone can create your first level-25 pet.\n\n2. Accept Pets Versus Pests and defeat Carrotus Maximus, Gorefu and Gnawface. Bring Aquatic attacks for the Elemental carrot, Flying attacks for the Aquatic Gorefu and Beast attacks for the Critter rat. A rare level-25 Ikky can use Black Claw followed by Flock against each, with healthy backups. Turn in the quest to open the Menagerie.\n\n3. Buy and build the Menagerie upgrades through the Architect Table. Earn Draenic Pet Battler for the level 3 blueprint; the current requirement is 150 pet battles in Draenor, not the original 500. Keep battling ordinary wild pets while collecting the Draenor Safari species, then finish the level 3 construction.\n\n4. Accept the available account-wide Menagerie daily before fighting: Battle Pet Roundup at Lunarfall or Scrappin' at Frostwall. Inspect today's opponents, choose family counters and time dodges for large attacks. Win the full battle and turn in the daily at your level 3 Menagerie.\n\n5. Open Big Bag of Pet Supplies (118697) for a chance at Sun Sproutling. Other Menagerie pets or no pet are possible. Learn the item if it appears; otherwise repeat after the daily reset or buy this exact species as a cage. The same account-wide daily is not a new bag on every alt.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=83588",
    },
    [1435] = {
        category = "Pet Battles",
        source = "Wild capture - the plains and Hallvalor, Draenor Nagrand",
        description = "Capture Leatherhide Runt in a wild pet battle. Search the documented habitat for a green paw, rather than attacking ordinary critters with character abilities.",
        difficulty = "medium",
        difficultyReason = "Limited primary spawns, phasing or an uncommon backline can extend the search.",
        requirements = "Battle Pet Training, a usable trap and a healthy team suited to Draenor's level-23 to level-25 wild pets",
