        name = "Leatherhide Runt",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Limited primary spawns, phasing or an uncommon backline can extend the search.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to the plains and Hallvalor, Draenor Nagrand. Follow clefthoof herds across the plains near 70,56. These are primary pets, not ordinary backline companions. Check the hut with cages at Hallvalor 85,55; if a capturable runt is behind a cage, try an adjacent open stall or another angle. Use the open plains if the battle area is obstructed.\n\n3. Engage the green-paw pet and check the enemy names. If Leatherhide Runt is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Leatherhide Runt below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=89198",
