        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A normal level-23 to level-25 wild capture with a prepared team.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to Draenor Nagrand's rivers and fungal grove. Follow riverbanks and lake outlets, including the northern mushroom grove. Ordinary frogs without paws are not battle pets. Mud Jumpers also occur in Talador and Spires of Arak; inspect local aquatic battles if you are already collecting there.\n\n3. Engage the green-paw pet and check the enemy names. If Mud Jumper is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Mud Jumper below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
