            "https://www.wowhead.com/quest=37644",
            "https://www.wowhead.com/quest=37645",
            "https://www.wowhead.com/npc=83817",
            "https://www.wowhead.com/item=113623",
            "https://www.wowhead.com/npc=83817#comments:id=2075911",
        },
        tips = "Albino Chimaeraling is not a Tamed Chimaera drop. Ghastly Kid is not guaranteed from beating Eleanor. Battle Pet Roundup / Scrappin' reward the Big Bag at Menagerie level 3; old journal wording may still call the source Mastering the Menagerie.",
        waypoints = {
            { mapID = 582, x = 0.28600000000000003, y = 0.392, step = 2, label = "Lio the Lioness - Menagerie" },
            { mapID = 590, x = 0.326, y = 0.42200000000000004, step = 2, label = "Serr'ah - Menagerie" },
        },
        npcId = 83817,
        petNPCID = 83817,
        name = "Ghastly Kid",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.\n\n1. Upgrade your Garrison to level 3 and learn Battle Pet Training. Accept Unearthed Magic from Lio the Lioness (Alliance) or Serr'ah (Horde), collect the Strange Stone near the mine entrance and return it. Its Ultimate Battle-Training Stone can create your first level-25 pet.\n\n2. Accept Pets Versus Pests and defeat Carrotus Maximus, Gorefu and Gnawface. Bring Aquatic attacks for the Elemental carrot, Flying attacks for the Aquatic Gorefu and Beast attacks for the Critter rat. A rare level-25 Ikky can use Black Claw followed by Flock against each, with healthy backups. Turn in the quest to open the Menagerie.\n\n3. Buy and build the Menagerie upgrades through the Architect Table. Earn Draenic Pet Battler for the level 3 blueprint; the current requirement is 150 pet battles in Draenor, not the original 500. Keep battling ordinary wild pets while collecting the Draenor Safari species, then finish the level 3 construction.\n\n4. Accept the available account-wide Menagerie daily before fighting: Battle Pet Roundup at Lunarfall or Scrappin' at Frostwall. Inspect today's opponents, choose family counters and time dodges for large attacks. Win the full battle and turn in the daily at your level 3 Menagerie.\n\n5. Open Big Bag of Pet Supplies (118697) for a chance at Ghastly Kid. Other Menagerie pets or no pet are possible. Learn the item if it appears; otherwise repeat after the daily reset or buy this exact species as a cage. The same account-wide daily is not a new bag on every alt.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=83817",
    },
    [1446] = {
        category = "Quest Rewards",
        source = "New Babies - Ring of Trials, Nagrand",
        itemId = 114834,
        description = "Establish your Nagrand outpost, then complete Digrem Orebar's food and calf-coaxing errands.",
        difficulty = "medium",
        difficultyReason = "Faction-specific outpost prerequisites precede the three short reward quests.",
        requirements = "An unfinished New Babies quest, or a purchased cage",
        cost = "No currency",
        commentIDs = { 1977265, 2061772 },
        references = {
            "https://www.wowhead.com/quest=34900",
            "https://www.wowhead.com/npc=84330",
            "https://www.wowhead.com/item=114834",
            "https://www.wowhead.com/npc=84330#comments:id=1977265",
            "https://www.wowhead.com/npc=84330#comments:id=2061772",
        },
        waypoints = {
            {
                mapID = 550,
                x = 0.863,
                y = 0.6609999999999999,
                step = 1,
                label = "Nagrand eastern entry - faction story handoff",
            },
            { mapID = 550, x = 0.63, y = 0.619, step = 1, label = "Telaari Station - Alliance outpost" },
            { mapID = 550, x = 0.8290000000000001, y = 0.441, step = 1, label = "Wor'var - Horde outpost" },
            { mapID = 550, x = 0.792, y = 0.526, step = 3, label = "Digrem Orebar - food errands and New Babies" },
        },
        npcId = 84330,
        petNPCID = 84330,
        name = "Meadowstomper Calf",
        warlordsPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Faction-specific outpost prerequisites precede the three short reward quests.\n\n1. Enter Nagrand in Draenor and complete your faction outpost introduction. Alliance starts The Might of the Warsong at the eastern entry then develops Telaari Station through D'kaan, Thaelin and Mo'mor. Horde follows Thrall at Wor'var, the lazy peons and Lantresor's Hallvalor / Masters' Cavern story.\n\n2. Use the outpost Drafting Table for A Choice to Make. Either the Corral or Tankworks choice can advance this story; the pet is not restricted to one building. Continue to Digrem Orebar at the Ring of Trials 79.2,52.6.\n\n3. Accept Tastes Like Chicken and collect ten Raw Windroc from the local windroc. Return to Digrem, then take Fruitful Ventures and gather fifteen Nagrand Cherries. Hand each quest in before expecting New Babies.\n\n4. Accept New Babies. Use the supplied coaxing interaction on five Tenderhoof Meadowstompers, searching the waterholes of Stonecrag Gorge. Stay close enough and let the interaction complete; killing the calves does not satisfy the rescue/coax objective.\n\n5. Return to Digrem and choose/claim Meadowstomper Calf, then learn the item. The green/olive calf is the correct reward; the blue transparent elephant is Trunks from a different achievement.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=84330",
    },
    [1447] = {
        category = "Pet Battles",
        source = "Wild capture - Moonlit Shore, north and south of Karabor",
        description = "Capture Moonshell Crab in a wild pet battle. Search the documented habitat for a green paw, rather than attacking ordinary critters with character abilities.",
        difficulty = "easy",
        difficultyReason = "A normal level-23 to level-25 wild capture with a prepared team.",
        requirements = "Battle Pet Training, a usable trap and a healthy team suited to Draenor's level-23 to level-25 wild pets",
        cost = "No currency; these wild captures cannot be caged",
        commentIDs = { 2033955, 2042572, 2049198 },
        tips = "Take any quality for collection credit and upgrade it with a battle-stone later. Clear nearby hostile creatures before starting, stand on unobstructed ground and heal between attempts. Old random-group realm hopping is not a reliable Retail method.",
        waypoints = { { mapID = 539, x = 0.6767, y = 0.342, step = 2, label = "Moonlit Shore - primary Moonshell Crabs" } },
        npcId = 82045,
        petNPCID = 82045,
        name = "Moonshell Crab",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A normal level-23 to level-25 wild capture with a prepared team.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to Moonlit Shore, north and south of Karabor. Start on the northern beach toward Elodor and follow the waterline around Karabor. Find the crab as a primary; swimming or cliffs can obstruct battles, so stand on dry shore and approach a reachable crab. Do not rely on ordinary Shadowmoon backlines for this species.\n\n3. Engage the green-paw pet and check the enemy names. If Moonshell Crab is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Moonshell Crab below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=82045",
        references = {
            "https://www.wowhead.com/npc=82045",
            "https://www.wowhead.com/npc=82045#comments:id=2033955",
            "https://www.wowhead.com/npc=82045#comments:id=2042572",
            "https://www.wowhead.com/npc=82045#comments:id=2049198",
        },
    },
    [1448] = {
