        },
        npcId = 84441,
        petNPCID = 84441,
        name = "Sea Calf",
        warlordsPetGuide = true,
        sourceType = "Vendor",
        stepCount = 5,
        acquisition = "Difficulty: Hard - Fishing Shack unlocks, Nat recruitment and fifty lunker/coin rewards require sustained fishing from scratch.\n\n1. Open the Fishing Shack, then work toward Draenor Angler by catching the required enormous fish in Draenor's six main zones. Train Draenor Fishing and use fishing equipment/lures. Buy and construct the level 3 Shack blueprint when unlocked.\n\n2. Take Luring Nat from the Shack NPC, catch its special fish, then complete Finding Nat Pagle at Anglers Wharf in Krasarang Wilds. Accept The Great Angler Returns BEFORE leaving Nat and return to your Garrison. Finish A True Draenor Angler's six special lunkers and An Angler on Our Team to recruit him.\n\n3. Assign Nat to the Fishing Shack, fish ordinary Draenor lunkers in the appropriate zones and turn them in to him. These hand-ins award Nat's Lucky Coins and friendship. The ordinary repeatable lunkers are different from his recruitment-quest fish. Save fifty coins.\n\n4. Buy Sea Calf from Nat at your Garrison Fishing Shack for fifty coins and learn it. Unlike Land Shark, this purchase does not add the Good Friend friendship requirement. Sea Calf and River Calf are different species.\n\n5. If you do not want the recruitment and fishing grind, buy the exact Sea Calf item/cage from a player. Do not copy fixed gold prices from old comments; prices depend on the current market.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=84441",
        references = {
            "https://www.wowhead.com/npc=84441",
            "https://www.wowhead.com/item=114919",
            "https://www.wowhead.com/npc=84441#comments:id=2311394",
        },
    },
    [1450] = {
        category = "Reputation",
        source = "Council of Exarchs - Revered",
        itemId = 119142,
        faction = "Alliance",
        description = "Earn the named reputation on the purchasing character, save the Apexis/gold price, then buy the companion.",
        difficulty = "medium",
        difficultyReason = "Simple legacy combat, but reputation and currency collection require a sustained route.",
        requirements = "Council of Exarchs - Revered on an Alliance character",
        cost = "2,000 Apexis Crystals plus 1,000 gold base price, reduced by applicable reputation discounts",
        commentIDs = { 2626221 },
        tips = "A learned pet cage bypasses the vendor's reputation and purchasing-faction requirements. Draenor Timewalking commendations, when available from the current event vendor, can supplement the grind; check the actual faction token rather than buying a similarly named Outland token.",
        waypoints = { { mapID = 622, x = 0.466, y = 0.767, step = 4, label = "Vindicator Nuurem - Stormshield Town Hall" } },
        areaMaps = { 539, 542 },
        npcId = 84885,
        petNPCID = 84885,
        name = "Draenei Micro Defender",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use an Alliance character and check its Council of Exarchs reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Complete Shadowmoon Valley's Alliance story quests and other Council-rewarding Draenor quests, then kill eligible enemies in level-appropriate Council reputation areas such as Pillars of Fate. Check your Council standing; the Horde's Frostwolf reputation does not substitute.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Buy the pet from Vindicator Nuurem inside Stormshield's Town Hall at 46.6,76.7. Use the Ashran Stormshield map, not Outland or Draenor Shadowmoon as the vendor map.\n\n5. Use the purchased item to learn Draenei Micro Defender. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=84885",
        references = {
            "https://www.wowhead.com/npc=84885",
            "https://www.wowhead.com/item=119142",
            "https://www.wowhead.com/npc=84885#comments:id=2626221",
        },
    },
