        name = "Bone Wasp",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use an Horde character and check its Laughing Skull Orcs reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Build and upgrade the Trading Post to level 2 in your Horde Garrison to open Laughing Skull reputation. Kill eligible enemies at the Pit or Everbloom Wilds in Gorgrond until Revered; an ordinary Tavern does not unlock this faction's quartermaster.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Return to Kil'rip at the level 2-or-higher Trading Post in Frostwall and buy Bone Wasp. The plot can be moved, so the Garrison pin is a building reference rather than a fixed vendor position.\n\n5. Use the purchased item to learn Bone Wasp. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
