        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Limited primary spawns, phasing or an uncommon backline can extend the search.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to southern Spires of Arak between Southport and Pinchwhistle. Search southeast of Axefall and near 48,65 west of Bloodmane Valley. Visible primary wasps can be sparse: sweep the road and vegetation toward Pinchwhistle rather than waiting at one point. Secure any quality and use a stone later.\n\n3. Engage the green-paw pet and check the enemy names. If Bloodsting Wasp is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Bloodsting Wasp below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=85255",
        references = {
            "https://www.wowhead.com/npc=85255",
            "https://www.wowhead.com/npc=85255#comments:id=2006535",
            "https://www.wowhead.com/npc=85255#comments:id=2079501",
            "https://www.wowhead.com/npc=85255#comments:id=2167509",
            "https://www.wowhead.com/npc=85255#comments:id=2325230",
        },
    },
