    [1467] = {
        category = "Drop",
        source = "Blingtron Gift Package - 4000 / 5000",
        itemId = 115483,
        description = "A random gift-package pet. You can use somebody else's Blingtron without learning Engineering.",
        difficulty = "medium",
        difficultyReason = "The daily gift and its random pet result require repeated eligible packages.",
        requirements = "An available Blingtron daily gift, or a pet cage",
        cost = "No vendor price",
        commentIDs = { 2012966, 2013589, 2258965 },
        areaMaps = { 84, 85 },
        npcId = 85284,
        petNPCID = 85284,
        name = "Sky-Bo",
        warlordsPetGuide = true,
        sourceType = "Drop",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The daily gift and its random pet result require repeated eligible packages.\n\n1. Find a player-deployed Blingtron 4000 or Blingtron 5000. Ask an engineer or watch a populated hub; do not confuse these with an ordinary mechanical NPC or a summoned battle pet.\n\n2. Accept and complete the available Blingtron gift quest, then open the resulting Gift Package. You do not need Engineering to receive it. The Blingtron daily gift is limited, so changing engineer or machine is not an unlimited supply of packages.\n\n3. Check the contents for Sky-Bo and learn its item if awarded. Comments confirm this pet from both the 4000 and 5000 packages, correcting the old 5000-only source.\n\n4. Repeat on later eligible days or buy the Sky-Bo cage. Engineering a machine gives access to a daily opportunity, not a guaranteed pet.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=85284",
        references = {
            "https://www.wowhead.com/npc=85284",
