        acquisition = "Difficulty: Easy - A normal level-23 to level-25 wild capture with a prepared team.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to Gorgrond's jungle and Broken Horn Village. Search for primary hatchlings and inspect Junglebeak, Wood Wasp and Twilight Wasp teams. Comments also report backlines near the Iron Docks. Choose another battle if a bird is stuck too far above the ground.\n\n3. Engage the green-paw pet and check the enemy names. If Axebeak Hatchling is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Axebeak Hatchling below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
