    [1471] = {
        category = "Treasure",
        source = "Mysterious Egg - Grom'gar, Frostfire Ridge",
        itemId = 117564,
        description = "Collect the egg from the sheltered nest and let its three-day timer finish.",
        difficulty = "easy",
        difficultyReason = "A reachable outdoor treasure followed by a passive three-day hatch timer.",
        requirements = "Space for the Mysterious Egg, or a pet cage",
        cost = "No currency",
        commentIDs = { 1990265, 2038738, 2310960 },
        waypoints = {
            { mapID = 525, x = 0.65, y = 0.61, step = 1, label = "Snowy hill - foot approach" },
            { mapID = 525, x = 0.65, y = 0.65, step = 1, label = "Hilltop - drop to canopy" },
            { mapID = 525, x = 0.643, y = 0.6579999999999999, step = 2, label = "Wiggling Egg - sheltered Rylak nest" },
        },
        npcId = 85387,
        petNPCID = 85387,
        name = "Fruit Hunter",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A reachable outdoor treasure followed by a passive three-day hatch timer.\n\n1. Travel to Grom'gar in Frostfire Ridge. With a flying mount, land at the Rylak-nest canopy around 64.3,65.8. On foot, start at the snowy hill around 65,61 and climb toward 65,65.\n\n2. From the hilltop drop onto the roof/platform, turn around and look UNDER the canopy. Find the nest with the Wiggling Egg and loot Mysterious Egg (112107). The exposed nests on top are easy to mistake for the correct sheltered one.\n\n3. Keep the egg while its three-day real-time timer runs. It becomes Cracked Egg (112108); open that container and collect Fruit Hunter (117564). The nest is not a rare-mob drop and does not immediately teach the pet.\n\n4. Use the Fruit Hunter item to learn the companion. If you want it immediately or this character has already claimed the treasure, compare pet cages on the Auction House.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=85387",
        references = {
            "https://www.wowhead.com/npc=85387",
