            "https://www.wowhead.com/npc=85387#comments:id=1990265",
            "https://www.wowhead.com/npc=85387#comments:id=2038738",
            "https://www.wowhead.com/npc=85387#comments:id=2310960",
        },
    },
    [1495] = {
        category = "Professions",
        source = "Node-triggered Goren Protector - Draenor Mining",
        description = "Harvest outdoor nodes, then loot the specific mob spawned by gathering. This pet is not a direct result of every node.",
        difficulty = "hard",
        difficultyReason = "Two random events are needed: spawning the correct gathering mob and then receiving its uncommon pet drop.",
        requirements = "Mining for outdoor gathering, or a purchased pet cage",
        cost = "No vendor price; gathering time or player-set cage price",
        commentIDs = { 1985537 },
        areaMaps = { 525, 543, 535, 539, 550, 542 },
        npcId = 85667,
        petNPCID = 85667,
        name = "Ore Eater",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Two random events are needed: spawning the correct gathering mob and then receiving its uncommon pet drop.\n\n1. Train Mining on the character gathering in Draenor, enable its minimap tracking, and clear enough bag space for nodes and loot. A high-level character makes the spawned mob easier to defeat.\n\n2. Mine outdoor Draenor ore veins. A Goren Protector can emerge while you harvest a node; kill and loot it for the pet chance. Use outdoor nodes if your Garrison mine produces no Protectors, as recent replies specifically report this problem.\n\n3. Make an ore circuit in Frostfire Ridge, including the Bladespire area, mining every reachable node. The Frostwall/Lunarfall Goren wandering in the mine are different mobs and are not the pet farm.\n\n4. When Goren Protector spawns, defeat it and loot the corpse. Learn Ore Eater if it drops; otherwise continue gathering new nodes. There is no guaranteed number of mobs, and buying the caged species avoids the random farm.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=85667",
        references = { "https://www.wowhead.com/npc=85667", "https://www.wowhead.com/npc=85667#comments:id=1985537" },
    },
    [1515] = {
        category = "Treasure",
        source = "Ketya's Stash - Ketya's Hideaway, Talador",
        description = "A cave treasure behind moving hazards; the correct entrance and chest are separate map pins.",
        difficulty = "easy",
        difficultyReason = "A short cave route; avoid the beams rather than trying to tank their damage.",
        requirements = "Access to northern Talador, or a pet cage",
        cost = "No currency",
        commentIDs = { 2010745, 2208777 },
        waypoints = {
            { mapID = 535, x = 0.5329999999999999, y = 0.258, step = 1, label = "Ketya's Hideaway entrance" },
            { mapID = 535, x = 0.54, y = 0.27699999999999997, step = 3, label = "Ketya's Stash - inside cave" },
        },
        npcId = 85231,
        petNPCID = 85231,
        name = "Stonegrinder",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short cave route; avoid the beams rather than trying to tank their damage.\n\n1. Travel to Archenon Siegeyard in northern Talador and take the downhill path west to Ketya's Hideaway at 53.3,25.8. The treasure marker at 54.0,27.7 is inside the cave, not an entrance on top of the hill.\n\n2. Enter and watch the moving laser beams. Avoid the red dashed circles that slow movement, and cross when the beam passes. Blue-green solid circles are the safer route; high character level does not make avoidable cave hazards a useful shortcut.\n\n3. Reach the rear of the cave around 54.0,27.7 and loot Ketya's Stash. Collect the pet item and use it to learn Stonegrinder.\n\n4. If this character already collected the treasure, check an unfinished character or buy a Stonegrinder cage. Farming arbitrary Talador rares is not this pet's source.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=85231",
        references = {
            "https://www.wowhead.com/npc=85231",
            "https://www.wowhead.com/npc=85231#comments:id=2010745",
            "https://www.wowhead.com/npc=85231#comments:id=2208777",
        },
    },
    [1524] = {
        category = "Rare Drops",
        source = "Netherspawn - Draenor outdoor rare",
        itemId = 116815,
        description = "Find the named outdoor rare, defeat it and learn its pet reward.",
        difficulty = "easy",
        difficultyReason = "A short legacy rare encounter; finding a live rare is the main delay.",
        requirements = "A character eligible for the rare's loot, or a purchased cage",
        cost = "No currency",
        commentIDs = { 1985539 },
        waypoints = {
            { mapID = 550, x = 0.47600000000000003, y = 0.7040000000000001, step = 2, label = "Netherspawn - rare location" },
        },
        npcId = 86081,
        petNPCID = 86081,
        name = "Netherspawn, Spawn of Netherspawn",
        warlordsPetGuide = true,
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short legacy rare encounter; finding a live rare is the main delay.\n\n1. Use a character that has not already claimed this one-time outdoor rare reward. Bring bag space and enough character power to defeat the rare; pet-battle levels are irrelevant to this kill.\n\n2. Search SOUTH of Oshu'gun in Draenor Nagrand, around 47.6,70.4. This is not Outland Nagrand and the summoned companion is not the rare you must kill.\n\n3. Tag and defeat Netherspawn, then loot the corpse and use the Netherspawn, Spawn of Netherspawn item. Check your journal and bags before assuming an empty later kill means the pet was removed.\n\n4. If the rare is already dead, return after a respawn. If this character has already claimed its reward, use an unfinished character or buy the exact pet cage instead of repeatedly farming unrelated creatures.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86081",
        references = {
            "https://www.wowhead.com/npc=86081",
            "https://www.wowhead.com/item=116815",
            "https://www.wowhead.com/npc=86081#comments:id=1985539",
        },
    },
    [1530] = {
        category = "Professions",
        source = "Rare Draenor Clans Archaeology solve",
        itemId = 117380,
        description = "Find the rare artifact project and solve it; it is not a random pet drop from ordinary dig-site enemies.",
        difficulty = "hard",
        difficultyReason = "The rare project is random and needs a substantial collection of the matching fragments.",
        requirements = "Archaeology and access to Draenor dig sites, or a purchased cage",
        cost = "175 matching fragments before keystone reductions",
        commentIDs = { 2058388 },
        areaMaps = { 525, 550 },
        npcId = 86422,
        petNPCID = 86422,
        name = "Frostwolf Ghostpup",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Hard - The rare project is random and needs a substantial collection of the matching fragments.\n\n1. Train Archaeology and travel to Draenor. Open the profession and world map to see this character's active dig sites. Their positions rotate, so the guide shows the useful zones rather than claiming that one fixed dig site is always active.\n\n2. Survey active Draenor Clans sites and collect that culture's fragments. Follow the Survey indicator until a find is close, then loot it. Clear other active Draenor sites when you need a new site of the desired culture to appear.\n\n3. Solve common projects to reveal new projects until Ancient Frostwolf Fang appears as the rare artifact. Save 175 fragments for it; inserting the permitted Draenor Clan Orator Canes can reduce the fragment requirement. Do not stop at an obsolete historical fragment-cap warning.\n\n4. Solve the rare project and learn the resulting pet item. The rare is completed once per character; another archaeologist can find their own project, or you can buy the caged pet. A pristine common-artifact quest is not the same reward.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86422",
        references = {
            "https://www.wowhead.com/npc=86422",
            "https://www.wowhead.com/item=117380",
            "https://www.wowhead.com/npc=86422#comments:id=2058388",
        },
    },
    [1531] = {
        category = "Professions",
        source = "Rare Arakkoa Archaeology solve",
        itemId = 117354,
        description = "Find the rare artifact project and solve it; it is not a random pet drop from ordinary dig-site enemies.",
        difficulty = "hard",
        difficultyReason = "The rare project is random and needs a substantial collection of the matching fragments.",
        requirements = "Archaeology and access to Draenor dig sites, or a purchased cage",
        cost = "225 matching fragments before keystone reductions",
        commentIDs = { 2152085 },
        areaMaps = { 542, 535 },
        npcId = 86420,
        petNPCID = 86420,
        name = "Ancient Nest Guardian",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Hard - The rare project is random and needs a substantial collection of the matching fragments.\n\n1. Train Archaeology and travel to Draenor. Open the profession and world map to see this character's active dig sites. Their positions rotate, so the guide shows the useful zones rather than claiming that one fixed dig site is always active.\n\n2. Survey active Arakkoa sites and collect that culture's fragments. Follow the Survey indicator until a find is close, then loot it. Clear other active Draenor sites when you need a new site of the desired culture to appear.\n\n3. Solve common projects to reveal new projects until Ancient Nest Guardian appears as the rare artifact. Save 225 fragments for it; inserting the permitted Arakkoa Ciphers can reduce the fragment requirement. Do not stop at an obsolete historical fragment-cap warning.\n\n4. Solve the rare project and learn the resulting pet item. The rare is completed once per character; another archaeologist can find their own project, or you can buy the caged pet. A pristine common-artifact quest is not the same reward.",
        reviewedAt = "2026-11-14",
        waypoints = {},
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86420",
        references = {
            "https://www.wowhead.com/npc=86420",
            "https://www.wowhead.com/item=117354",
            "https://www.wowhead.com/npc=86420#comments:id=2152085",
        },
    },
    [1532] = {
        category = "Quest Rewards",
        source = "Spires of Arak story - Ikky (34898)",
        description = "Open Veil Terokk and your faction outpost, help the egg hatch, feed Ikky and reunite with him in town.",
        difficulty = "medium",
        difficultyReason = "A fresh character needs the Skettis/Veil Terokk and outpost introductions before the short egg chain.",
        requirements = "An unfinished Ikky reward quest, or a purchased cage",
        cost = "No currency",
        commentIDs = { 2035153, 2189351, 3133566, 3217841 },
        waypoints = {
            { mapID = 542, x = 0.37799999999999995, y = 0.18, step = 1, label = "Azik - start The Shadows of Skettis" },
            { mapID = 542, x = 0.436, y = 0.129, step = 1, label = "Skettis - Reshad's tasks" },
            { mapID = 542, x = 0.516, y = 0.312, step = 1, label = "Crow's Crook - The Crone and follow-ups" },
            { mapID = 542, x = 0.46, y = 0.46, step = 2, label = "Veil Terokk - story / outpost handoff" },
            { mapID = 542, x = 0.401, y = 0.434, step = 2, label = "Axefall - Horde outpost" },
            { mapID = 542, x = 0.39899999999999997, y = 0.607, step = 2, label = "Southport - Alliance outpost" },
            { mapID = 542, x = 0.45399999999999996, y = 0.366, step = 3, label = "Shadowglade - gavel, egg and grubs" },
            { mapID = 542, x = 0.462, y = 0.456, step = 5, label = "Ikky - final reward at Veil Terokk" },
        },
        npcId = 86447,
        petNPCID = 86447,
        name = "Ikky",
        warlordsPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 6,
        acquisition = "Difficulty: Medium - A fresh character needs the Skettis/Veil Terokk and outpost introductions before the short egg chain.\n\n1. Start with Azik at 37.8,18.0 in Spires of Arak for The Shadows of Skettis. Speak Reshad's password, finish the disguise and Adherent tasks, then follow The Crone to Crow's Crook. The quest route resumes the next unfinished stage if this character has already begun the story.\n\n2. Finish the Crow's Crook tasks and enter Veil Terokk with Reshad. Complete your faction's One of Our Own and Inspecting the Troops introductions, choose an outpost building at the Drafting Table and take Return to Veil Terokk.\n\n3. Accept The Kaliri Whisperer at Veil Terokk and search Skizzik's body in Shadowglade for the gavel. This makes the nearby Kaliri Egg at 45.4,36.6 interactable: you can hatch it before travelling back to hand in the gavel. Mother of Thorns is a nearby side task, not a mandatory additional pet prerequisite.\n\n4. Take Ikky's Egg and help it hatch. Accept Baby Bird from the hatchling, collect eight Ravager Grubs in Shadowglade and feed/hand them in to Ikky. He flies away after the feeding; this does not mean you lost the reward.\n\n5. Return to Veil Terokk around 46.2,45.6 and take Ikky (34898) from the waiting bird. Finish the interaction to learn the pet. Leave room below the journal's three-copy cap BEFORE completing this quest; older comments report a lost reward when already at three copies.\n\n6. The reward learns below rare quality; use a suitable battle-stone if you want a rare Ikky. Another unfinished character or a cage provides additional copies without repeating the already-completed character's reward.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86447",
        references = {
            "https://www.wowhead.com/npc=86447",
            "https://www.wowhead.com/npc=86447#comments:id=2035153",
            "https://www.wowhead.com/npc=86447#comments:id=2189351",
            "https://www.wowhead.com/npc=86447#comments:id=3133566",
            "https://www.wowhead.com/npc=86447#comments:id=3217841",
        },
    },
    [1533] = {
        category = "Dungeon and Raids",
        source = "The Lanticore - Heroic Upper Blackrock Spire",
        itemId = 117528,
        description = "Find the rare spawn inside the Warlords version of Heroic Upper Blackrock Spire.",
        difficulty = "hard",
        difficultyReason = "Both the rare's appearance and the personal pet reward can require repeat eligible heroic runs.",
        requirements = "Access to Heroic Upper Blackrock Spire, or a purchased cage",
        cost = "No currency",
        commentIDs = { 1990061, 1994709, 2522655 },
        waypoints = { { mapID = 33, x = 0.7894, y = 0.3362, step = 1, label = "Blackrock Mountain - Upper Blackrock Spire entrance" } },
        npcId = 86532,
        petNPCID = 86532,
        name = "Lanticore Spawnling",
        warlordsPetGuide = true,
        sourceType = "Dungeon and Raids",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Both the rare's appearance and the personal pet reward can require repeat eligible heroic runs.\n\n1. Travel to Blackrock Mountain and enter the Warlords Upper Blackrock Spire, reached from the upper interior platform around 78.9,33.6 on the Blackrock Mountain map. Select HEROIC before entering; the classic Lower Blackrock Spire route is a different instance.\n\n2. Clear Orebender Gor'ashan's room and proceed toward Kyrak through the early dungeon. Look in the side alcove near Kyrak's area for The Lanticore; the rare does not appear in every run.\n\n3. If it is present, tag and defeat The Lanticore and loot for Lanticore Spawnling. Later comments contradict the old assumption of a guaranteed personal drop, so an empty corpse does not prove the source is wrong.\n\n4. Learn the pet if awarded. Otherwise use another eligible character or return after the heroic loot reset. Do not treat resetting a saved heroic as unlimited new pet attempts. Buying a cage avoids both spawn and loot randomness.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86532",
