        npcId = 86716,
        petNPCID = 86716,
        name = "Crimson Spore",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A short outdoor treasure pickup; flying makes the approach straightforward.\n\n1. Travel to Tangleheart in Gorgrond at 57.1,65.3. Look upward at the mushroom caps rather than searching the ground for a rare spawn.\n\n2. Fly onto the mushroom supporting Strange Spore, or climb the nearby mushroom steps on foot and make the short jumps between caps. No jumping toy is required for the ordinary mushroom route.\n\n3. Click Strange Spore, loot Crimson Spore and use the item. This is a one-time treasure reward on that character; it is not a wild capture or a random drop from nearby spore creatures.",
