        npcId = 86717,
        petNPCID = 86717,
        name = "Umbrafen Spore",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A direct pickup with flight; the optional walking route needs careful ledge jumps.\n\n1. Travel to Umbrafen in Draenor Shadowmoon Valley. With flying, land directly on the mushroom at 55.8,20.0 and look for Strange Spore.\n\n2. Without flight, start at Exarch's Rise 60.5,20.6 and descend to the pool at 60.1,18.0. Find the ledge by 59.5,17.5, follow it southwest to 57.8,18.3, then drop two ledges toward 57.4,18.7.\n\n3. Follow the final ledge northwest to 56.2,18.4 and make the short jump to the mushroom at 55.8,20.0. Move carefully and use a slow-fall effect if available. The approach pins are optional when you can fly.\n\n4. Loot Strange Spore and use Umbrafen Spore to learn it. The similarly named Gorgrond treasure awards Crimson Spore instead. An unfinished character or a cage provides another copy after this treasure has been claimed.",
