    [1540] = {
        category = "Rare Drops",
        source = "Rotcap - Draenor outdoor rare",
        itemId = 118107,
        description = "Find the named outdoor rare, defeat it and learn its pet reward.",
        difficulty = "easy",
        difficultyReason = "A short legacy rare encounter; finding a live rare is the main delay.",
        requirements = "A character eligible for the rare's loot, or a purchased cage",
        cost = "No currency",
        commentIDs = { 2011306 },
        waypoints = { { mapID = 542, x = 0.382, y = 0.28, step = 2, label = "Rotcap - rare location" } },
        npcId = 86719,
        petNPCID = 86719,
        name = "Brilliant Spore",
        warlordsPetGuide = true,
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short legacy rare encounter; finding a live rare is the main delay.\n\n1. Use a character that has not already claimed this one-time outdoor rare reward. Bring bag space and enough character power to defeat the rare; pet-battle levels are irrelevant to this kill.\n\n2. Look in the small swamp beside the road at 38.2,28.0 in Spires of Arak. Rotcap is the rare fungus; there is no clickable Strange Spore treasure for this color.\n\n3. Tag and defeat Rotcap, then loot the corpse and use the Brilliant Spore item. Check your journal and bags before assuming an empty later kill means the pet was removed.\n\n4. If the rare is already dead, return after a respawn. If this character has already claimed its reward, use an unfinished character or buy the exact pet cage instead of repeatedly farming unrelated creatures.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=86719",
        references = {
