            "https://www.wowhead.com/item=118107",
            "https://www.wowhead.com/npc=86719#comments:id=2011306",
        },
    },
    [1541] = {
        category = "Treasure",
        source = "Varasha's Egg - Writhing Mire, Spires of Arak",
        itemId = 118207,
        description = "Disturb the cave egg, defeat Varasha, then return to the nest to loot the pet.",
        difficulty = "easy",
        difficultyReason = "One legacy rare fight and a second egg interaction.",
        requirements = "A character able to defeat Varasha, or a pet cage",
        cost = "No currency",
        commentIDs = { 1992609, 2008910, 2495198 },
        waypoints = {
            { mapID = 542, x = 0.314, y = 0.434, step = 1, label = "Varasha cave entrance" },
            { mapID = 542, x = 0.294, y = 0.41200000000000003, step = 2, label = "Varasha's Egg - summon, defeat, then loot" },
        },
        npcId = 86879,
        petNPCID = 86879,
        name = "Hydraling",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 3,
        acquisition = "Difficulty: Easy - One legacy rare fight and a second egg interaction.\n\n1. Go to the Writhing Mire in Spires of Arak and enter the cave at 31.4,43.4. Follow it toward the nest around 29.4,41.2; the egg coordinate is deeper in the cave.\n\n2. Click Varasha's Egg to summon the hydra, then defeat Varasha. Do not leave after looting only the corpse: the companion reward is in the nest interaction.\n\n3. Return to the egg and loot Hydraling, then use the learning item. If a second click wrongly summons another hydra, finish the fight and try reloading/re-entering before interacting again; a reply documents this workaround.",
        reviewedAt = "2026-11-14",
