    [1542] = {
        category = "Reputation",
        source = "Frostwolf Orcs - Revered",
        itemId = 119141,
        faction = "Horde",
        description = "Earn the named reputation on the purchasing character, save the Apexis/gold price, then buy the companion.",
        difficulty = "medium",
        difficultyReason = "Simple legacy combat, but reputation and currency collection require a sustained route.",
        requirements = "Frostwolf Orcs - Revered on an Horde character",
        cost = "2,000 Apexis Crystals plus 1,000 gold base price, reduced by applicable reputation discounts",
        commentIDs = { 2282811 },
        tips = "A learned pet cage bypasses the vendor's reputation and purchasing-faction requirements. Draenor Timewalking commendations, when available from the current event vendor, can supplement the grind; check the actual faction token rather than buying a similarly named Outland token.",
        waypoints = {
            { mapID = 624, x = 0.539, y = 0.626, step = 4, label = "Beska Redtusk - Frostwolf Pup" },
            { mapID = 525, x = 0.45, y = 0.15, step = 2, label = "Stonefury Cliffs - reputation area reference" },
        },
        npcId = 87111,
        petNPCID = 87111,
        name = "Frostwolf Pup",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use an Horde character and check its Frostwolf Orcs reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Complete the Horde Frostfire Ridge story and other Frostwolf-rewarding quests, then continue with eligible enemies in Frostfire reputation areas such as Stonefury Cliffs or Magnarok. The companion's requirement is Revered; the mount's Exalted requirement is a different purchase.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Visit Beska Redtusk in Warspear around 53.9,62.6 and buy Frostwolf Pup. Do not confuse it with Frostwolf Ghostpup from Archaeology.\n\n5. Use the purchased item to learn Frostwolf Pup. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=87111",
        references = {
            "https://www.wowhead.com/npc=87111",
            "https://www.wowhead.com/item=119141",
            "https://www.wowhead.com/npc=87111#comments:id=2282811",
        },
    },
    [1543] = {
        category = "Treasure",
        source = "Glass of Warm Milk - level 3 Garrison Barn",
        itemId = 120309,
        description = "Loot the small milk tankard in a completed level 3 Barn and use it to learn the cow.",
        difficulty = "hard",
        difficultyReason = "A fresh Barn needs the 125-order blueprint unlock and level 3 construction before the simple treasure pickup.",
        requirements = "Your own level 3 Barn; Pygmy Cow cannot be caged",
        cost = "Barn construction/upgrades and 125 Barn work orders for its blueprint",
        commentIDs = { 2066086, 2111050, 5223584 },
        references = {
            "https://www.wowhead.com/achievement=9565/master-trapper",
            "https://www.wowhead.com/npc=87257",
            "https://www.wowhead.com/item=120309",
            "https://www.wowhead.com/npc=87257#comments:id=2066086",
            "https://www.wowhead.com/npc=87257#comments:id=2111050",
            "https://www.wowhead.com/npc=87257#comments:id=5223584",
        },
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - building reference; plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - building reference; plot varies" },
        },
        npcId = 87257,
        petNPCID = 87257,
        name = "Pygmy Cow",
        warlordsPetGuide = true,
        sourceType = "Treasure",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A fresh Barn needs the 125-order blueprint unlock and level 3 construction before the simple treasure pickup.\n\n1. Build your own Barn on a medium Garrison plot. If the level 3 blueprint is locked, take the Barn's trap, weaken eligible Draenor beasts without killing them and lure them into the trap. Bring the captured animals back and place 125 BARN work orders for Master Trapper (9565). Ordinary profession work orders do not unlock this blueprint.\n\n2. Purchase and construct Barn level 3 at the Architect Table once Master Trapper is unlocked. A level 3 Town Hall alone does not upgrade the Barn, and visiting somebody else's Barn is not a reliable way to obtain your personal milk treasure.\n\n3. Search the finished Barn for Glass of Warm Milk: check the closed animal stall on the ground floor, near the water trough, and the upstairs shelf/loft. The tankard is small and may not sparkle like a normal quest item.\n\n4. If it is upstairs, use a flying mount to reach the loft opening and drop onto its shelf. Without flight, a controlled jump/glider or Slow Fall from nearby higher ground can reach it. Another documented option is swapping the Barn with your other medium plot at the Architect Table and checking its ground-floor milk position again.\n\n5. Loot Glass of Warm Milk and use it from your bags to learn Pygmy Cow. Check the ground floor before repeatedly attempting roof jumps; leaving and re-entering or moving the Barn can change the milk's position. This companion cannot be caged, so there is no Auction House pet bypass.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=87257",
    },
    [1545] = {
        category = "Pet Battles",
        source = "Big Bag of Pet Supplies - level 3 Garrison Menagerie daily",
        itemId = 118578,
        description = "A random pet inside the level 3 Menagerie's daily reward bag; the unlock quest does not guarantee this species.",
        difficulty = "hard",
        difficultyReason = "A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.",
        requirements = "Level 3 Menagerie for the full daily bag, or a purchased cage",
        cost = "Garrison/building upgrades and time; no pet currency purchase",
        commentIDs = { 2075907 },
        references = {
            "https://www.wowhead.com/item=118697",
            "https://www.wowhead.com/quest=37644",
            "https://www.wowhead.com/quest=37645",
            "https://www.wowhead.com/npc=87704",
            "https://www.wowhead.com/item=118578",
            "https://www.wowhead.com/npc=87704#comments:id=2075907",
        },
        tips = "Albino Chimaeraling is not a Tamed Chimaera drop. Ghastly Kid is not guaranteed from beating Eleanor. Battle Pet Roundup / Scrappin' reward the Big Bag at Menagerie level 3; old journal wording may still call the source Mastering the Menagerie.",
        waypoints = {
            { mapID = 582, x = 0.28600000000000003, y = 0.392, step = 2, label = "Lio the Lioness - Menagerie" },
            { mapID = 590, x = 0.326, y = 0.42200000000000004, step = 2, label = "Serr'ah - Menagerie" },
        },
        npcId = 87704,
        petNPCID = 87704,
        name = "Firewing",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.\n\n1. Upgrade your Garrison to level 3 and learn Battle Pet Training. Accept Unearthed Magic from Lio the Lioness (Alliance) or Serr'ah (Horde), collect the Strange Stone near the mine entrance and return it. Its Ultimate Battle-Training Stone can create your first level-25 pet.\n\n2. Accept Pets Versus Pests and defeat Carrotus Maximus, Gorefu and Gnawface. Bring Aquatic attacks for the Elemental carrot, Flying attacks for the Aquatic Gorefu and Beast attacks for the Critter rat. A rare level-25 Ikky can use Black Claw followed by Flock against each, with healthy backups. Turn in the quest to open the Menagerie.\n\n3. Buy and build the Menagerie upgrades through the Architect Table. Earn Draenic Pet Battler for the level 3 blueprint; the current requirement is 150 pet battles in Draenor, not the original 500. Keep battling ordinary wild pets while collecting the Draenor Safari species, then finish the level 3 construction.\n\n4. Accept the available account-wide Menagerie daily before fighting: Battle Pet Roundup at Lunarfall or Scrappin' at Frostwall. Inspect today's opponents, choose family counters and time dodges for large attacks. Win the full battle and turn in the daily at your level 3 Menagerie.\n\n5. Open Big Bag of Pet Supplies (118697) for a chance at Firewing. Other Menagerie pets or no pet are possible. Learn the item if it appears; otherwise repeat after the daily reset or buy this exact species as a cage. The same account-wide daily is not a new bag on every alt.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=87704",
    },
    [1563] = {
        category = "Drop",
        source = "Time-Locked Box - Ironmarch enemies, present-day Blasted Lands",
        itemId = 118675,
        description = "The Iron Horde invasion farm remains available after the original pre-expansion event.",
        difficulty = "medium",
        difficultyReason = "Easy legacy enemies but a low random box drop can take many kills.",
