            { mapID = 17, x = 0.42, y = 0.13, step = 2, label = "Okril'lon Hold - Ironmarch farm" },
            { mapID = 17, x = 0.6, y = 0.29, step = 2, label = "Iron Horde cave - alternative farm" },
        },
        npcId = 7546,
        petNPCID = 7546,
        name = "Bronze Whelpling",
        warlordsPetGuide = true,
        sourceType = "Drop",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Easy legacy enemies but a low random box drop can take many kills.\n\n1. Travel to Blasted Lands in the Eastern Kingdoms and use its PRESENT-DAY Iron Horde invasion phase. If you see the old landscape, ask Zidormi near the Swamp of Sorrows border to return you to the present.\n\n2. Farm Ironmarch enemies around Okril'lon Hold at 42,13, circling the outer guards, stairs and upper keep. Another option is the Iron Horde cave around 60,29. Ordinary low-level old-phase wildlife is not the intended farm.\n\n3. Loot each eligible enemy and check for Time-Locked Box (118675). The pet was not removed when the invasion's launch period ended; recent comments still report this exact farm. Kills have independent random chances, not an increasing guaranteed reward counter.\n\n4. Open Time-Locked Box and learn the Bronze Whelpling it contains. If you would rather skip the drop grind, buy a Bronze Whelpling cage. It is separate from the Iron Starlette quest reward available in the same zone.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=7546",
        references = {
            "https://www.wowhead.com/npc=7546",
            "https://www.wowhead.com/item=118675",
            "https://www.wowhead.com/npc=7546#comments:id=1993294",
            "https://www.wowhead.com/npc=7546#comments:id=2012768",
            "https://www.wowhead.com/npc=7546#comments:id=3187993",
            "https://www.wowhead.com/npc=7546#comments:id=6114173",
        },
    },
    [1564] = {
        category = "Rare Drops",
        source = "Mandrakor - Draenor outdoor rare",
        description = "Find the named outdoor rare, defeat it and learn its pet reward.",
        difficulty = "easy",
        difficultyReason = "A short legacy rare encounter; finding a live rare is the main delay.",
        requirements = "A character eligible for the rare's loot, or a purchased cage",
        cost = "No currency",
        commentIDs = { 2065851 },
        waypoints = {
            { mapID = 543, x = 0.49, y = 0.53, step = 2, label = "Mandrakor cave entrance" },
            { mapID = 543, x = 0.506, y = 0.532, step = 3, label = "Mandrakor - inside cave" },
        },
        npcId = 88103,
        petNPCID = 88103,
        name = "Doom Bloom",
        warlordsPetGuide = true,
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short legacy rare encounter; finding a live rare is the main delay.\n\n1. Use a character that has not already claimed this one-time outdoor rare reward. Bring bag space and enough character power to defeat the rare; pet-battle levels are irrelevant to this kill.\n\n2. Go to Steamscar Rise in Gorgrond. From the hilltop marker walk southwest to the cave mouth around 49,53, descend on its left side and enter; Mandrakor is inside, not on the surface above the pin.\n\n3. Tag and defeat Mandrakor, then loot the corpse and use the Doom Bloom item. Check your journal and bags before assuming an empty later kill means the pet was removed.\n\n4. If the rare is already dead, return after a respawn. If this character has already claimed its reward, use an unfinished character or buy the exact pet cage instead of repeatedly farming unrelated creatures.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=88103",
        references = { "https://www.wowhead.com/npc=88103", "https://www.wowhead.com/npc=88103#comments:id=2065851" },
    },
    [1565] = {
        category = "Professions",
        source = "Draenor Engineering or level 3 Engineering Works",
        itemId = 118741,
        description = "Craft the pet yourself, commission it through a level 3 Engineering Works, or buy the tradable companion.",
        difficulty = "medium",
        difficultyReason = "The craft is simple, but schematics and soulbound Gearspring Parts require profession cooldowns or building work orders.",
        requirements = "Draenor Engineering and the schematic, OR a level 3 Engineering Works",
        cost = "30 Gearspring Parts and 10 Blackrock Ore; engineer's schematic costs 1 Secret of Draenor Engineering",
        references = {
            "https://www.wowhead.com/spell=176732",
            "https://www.wowhead.com/npc=88134",
            "https://www.wowhead.com/item=118741",
            "https://www.wowhead.com/npc=88134#comments:id=2100283",
        },
        commentIDs = { 2100283 },
        tips = "Use Draenor Engineering's current skill panel. Launch-era '700 Engineering' refers to the old combined skill system. Engineering is not required to learn the pet. The Garrison map marks the hub because small-building plots can be rearranged.",
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - your building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - your building plot varies" },
        },
        npcId = 88134,
        petNPCID = 88134,
        name = "Mechanical Scorpid",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 5,
        acquisition = "Difficulty: Medium - The craft is simple, but schematics and soulbound Gearspring Parts require profession cooldowns or building work orders.\n\n1. If you only want the pet, compare the Auction House price for Mechanical Scorpid before building an entire workshop. Buying the correct pet or cage bypasses its crafting requirements.\n\n2. For an engineer, train Draenor Engineering and make a Secret of Draenor Engineering with the profession's daily recipe. Buy this pet's schematic from Zaren Hoffle in Lunarfall, Pozzlow in Frostwall, or the Engineering Plans vendor in your Ashran faction hub, then learn it.\n\n3. Produce Gearspring Parts with the Draenor Engineering recipe and/or Engineering Works work orders. Parts are soulbound: buying ordinary ore does not let a different character spend your parts. Save 30 Gearspring Parts and 10 Blackrock Ore on the character doing the craft.\n\n4. Without Engineering, upgrade your own Engineering Works to level 3 and use its crafting NPC's pet service. Complete 250 Garrison work orders for Working More Orders (9406) if its blueprint is locked, buy/build the upgrade, and collect the parts from work orders before requesting this pet.\n\n5. For a personal craft have the required Arclight Spanner or an equivalent engineering multitool available, then craft Mechanical Scorpid. Alternatively collect the NPC's crafted item. Use the learning item to add the pet. Each extra copy consumes another full set of materials.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=88134",
    },
    [1566] = {
        category = "Quest Rewards",
        source = "For the Birds - visiting Garrison Inn quest",
        description = "Accept the visitor's original pet quest, collect its dungeon object and defeat the final boss before returning.",
        difficulty = "medium",
        difficultyReason = "The Inn visitor is random and the quest includes a dungeon clear; a high-level character can usually solo the legacy instance.",
        requirements = "An Inn/Tavern with the correct visitor, or a purchased pet cage",
        cost = "Building access; no pet purchase currency",
        commentIDs = { 2020333 },
        references = {
            "https://www.wowhead.com/quest=37150",
            "https://www.wowhead.com/npc=88222",
            "https://www.wowhead.com/npc=88222#comments:id=2020333",
        },
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - building reference; plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - building reference; plot varies" },
            { mapID = 543, x = 0.595, y = 0.45299999999999996, step = 3, label = "The Everbloom entrance" },
        },
        npcId = 88222,
        petNPCID = 88222,
        name = "Everbloom Peachick",
        warlordsPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 5,
        acquisition = "Difficulty: Medium - The Inn visitor is random and the quest includes a dungeon clear; a high-level character can usually solo the legacy instance.\n\n1. Build Lunarfall Inn (Alliance) or Frostwall Tavern (Horde), then check its daily visitors for Mylune. The level 1 Inn can offer dungeon quests. Keep checking on later days if this visitor has not arrived.\n\n2. Accept For the Birds (quest 37150). Take the original pet reward quest, not a later replacement quest that only offers a different supply reward. Check the active objectives before leaving the Garrison.\n\n3. Enter The Everbloom on normal or heroic. Find the Tiny Peachick Hatchling in the nest tucked behind a root near the Ancient Protectors area. Loot the nest and also defeat Yalnu; early comments about sneaking in for the nest alone predate the added final-boss requirement.\n\n4. Return to Mylune at the Inn/Tavern and finish the hand-in. If the minimap points at an empty fountain, check upstairs rooms and behind the actual Inn, especially after moving the building. Keep the Inn built; leaving and re-entering can refresh which quest visitors are shown.\n\n5. Learn Everbloom Peachick from the quest reward. If the NPC will not accept the hand-in, confirm BOTH the object and final-boss objectives are complete. Buying a cage is the alternative to waiting for this visitor on an unfinished character.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=88222",
    },
    [1567] = {
        category = "Quest Rewards",
        source = "The Huntresses - visiting Garrison Inn quest",
        description = "Accept the visitor's original pet quest, collect its dungeon object and defeat the final boss before returning.",
        difficulty = "medium",
        difficultyReason = "The Inn visitor is random and the quest includes a dungeon clear; a high-level character can usually solo the legacy instance.",
        requirements = "An Inn/Tavern with the correct visitor, or a purchased pet cage",
        cost = "Building access; no pet purchase currency",
        commentIDs = { 2050936 },
        references = {
            "https://www.wowhead.com/quest=37164",
            "https://www.wowhead.com/npc=88225",
            "https://www.wowhead.com/npc=88225#comments:id=2050936",
        },
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - building reference; plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - building reference; plot varies" },
            { mapID = 539, x = 0.319, y = 0.425, step = 3, label = "Shadowmoon Burial Grounds entrance - Heroic" },
        },
        npcId = 88225,
        petNPCID = 88225,
        name = "Sentinel's Companion",
        warlordsPetGuide = true,
        sourceType = "Quest Rewards",
        stepCount = 5,
        acquisition = "Difficulty: Medium - The Inn visitor is random and the quest includes a dungeon clear; a high-level character can usually solo the legacy instance.\n\n1. Build Lunarfall Inn (Alliance) or Frostwall Tavern (Horde), then check its daily visitors for Cowled Ranger. The level 1 Inn can offer dungeon quests. Keep checking on later days if this visitor has not arrived.\n\n2. Accept The Huntresses (quest 37164). Take the original pet reward quest, not a later replacement quest that only offers a different supply reward. Check the active objectives before leaving the Garrison.\n\n3. Set the dungeon to HEROIC before entering Shadowmoon Burial Grounds. Clear through Nhallish, collect the glowing Silver-Lined Arrow behind the second boss and defeat Ner'zhul. A normal-mode clear does not satisfy this heroic quest.\n\n4. Return to Cowled Ranger at the Inn/Tavern and finish the hand-in. If the minimap points at an empty fountain, check upstairs rooms and behind the actual Inn, especially after moving the building. Keep the Inn built; leaving and re-entering can refresh which quest visitors are shown.\n\n5. Learn Sentinel's Companion from the quest reward. If the NPC will not accept the hand-in, confirm BOTH the object and final-boss objectives are complete. Buying a cage is the alternative to waiting for this visitor on an unfinished character.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=88225",
    },
    [1568] = {
        category = "Pet Battles",
        source = "Big Bag of Pet Supplies - level 3 Garrison Menagerie daily",
        itemId = 119467,
        description = "A random pet inside the level 3 Menagerie's daily reward bag; the unlock quest does not guarantee this species.",
        difficulty = "hard",
        difficultyReason = "A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.",
        requirements = "Level 3 Menagerie for the full daily bag, or a purchased cage",
        cost = "Garrison/building upgrades and time; no pet currency purchase",
        commentIDs = { 2075913 },
        references = {
            "https://www.wowhead.com/item=118697",
            "https://www.wowhead.com/quest=37644",
            "https://www.wowhead.com/quest=37645",
            "https://www.wowhead.com/npc=88300",
            "https://www.wowhead.com/item=119467",
            "https://www.wowhead.com/npc=88300#comments:id=2075913",
        },
        tips = "Albino Chimaeraling is not a Tamed Chimaera drop. Ghastly Kid is not guaranteed from beating Eleanor. Battle Pet Roundup / Scrappin' reward the Big Bag at Menagerie level 3; old journal wording may still call the source Mastering the Menagerie.",
        waypoints = {
            { mapID = 582, x = 0.28600000000000003, y = 0.392, step = 2, label = "Lio the Lioness - Menagerie" },
            { mapID = 590, x = 0.326, y = 0.42200000000000004, step = 2, label = "Serr'ah - Menagerie" },
        },
        npcId = 88300,
        petNPCID = 88300,
        name = "Puddle Terror",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.\n\n1. Upgrade your Garrison to level 3 and learn Battle Pet Training. Accept Unearthed Magic from Lio the Lioness (Alliance) or Serr'ah (Horde), collect the Strange Stone near the mine entrance and return it. Its Ultimate Battle-Training Stone can create your first level-25 pet.\n\n2. Accept Pets Versus Pests and defeat Carrotus Maximus, Gorefu and Gnawface. Bring Aquatic attacks for the Elemental carrot, Flying attacks for the Aquatic Gorefu and Beast attacks for the Critter rat. A rare level-25 Ikky can use Black Claw followed by Flock against each, with healthy backups. Turn in the quest to open the Menagerie.\n\n3. Buy and build the Menagerie upgrades through the Architect Table. Earn Draenic Pet Battler for the level 3 blueprint; the current requirement is 150 pet battles in Draenor, not the original 500. Keep battling ordinary wild pets while collecting the Draenor Safari species, then finish the level 3 construction.\n\n4. Accept the available account-wide Menagerie daily before fighting: Battle Pet Roundup at Lunarfall or Scrappin' at Frostwall. Inspect today's opponents, choose family counters and time dodges for large attacks. Win the full battle and turn in the daily at your level 3 Menagerie.\n\n5. Open Big Bag of Pet Supplies (118697) for a chance at Puddle Terror. Other Menagerie pets or no pet are possible. Learn the item if it appears; otherwise repeat after the daily reset or buy this exact species as a cage. The same account-wide daily is not a new bag on every alt.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=88300",
    },
    [1569] = {
        category = "Professions",
        source = "Draenor Blacksmithing",
        itemId = 119328,
        description = "Create the companion with Blacksmithing; a Garrison Forge by itself cannot commission it.",
        difficulty = "medium",
        difficultyReason = "A recipe-token cooldown and soulbound ingot production delay a fresh crafter.",
        requirements = "Draenor Blacksmithing for the personal craft",
        cost = "Recipe token plus 50 Truesteel Ingots and 10 Sorcerous Fire",
        commentIDs = { 1993304 },
        references = {
            "https://www.wowhead.com/spell=177169",
            "https://www.wowhead.com/npc=84853",
            "https://www.wowhead.com/item=119328",
            "https://www.wowhead.com/npc=84853#comments:id=1993304",
        },
        waypoints = {
            { mapID = 582, x = 0.4, y = 0.37, step = 1, label = "Lunarfall - your building plot varies" },
            { mapID = 590, x = 0.52, y = 0.5, step = 1, label = "Frostwall - your building plot varies" },
        },
        npcId = 84853,
        petNPCID = 84853,
        name = "Soul of the Forge",
        warlordsPetGuide = true,
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Medium - A recipe-token cooldown and soulbound ingot production delay a fresh crafter.\n\n1. Use a character with Draenor Blacksmithing, or compare Soul of the Forge cages on the Auction House. You do not need the profession to learn the companion.\n\n2. Make a Secret of Draenor Blacksmithing using its daily profession recipe and buy Plans: Soul of the Forge from a Draenor blacksmithing recipe vendor in the Garrison Forge or your Ashran hub. Learn the plan on the crafter.\n\n3. Produce fifty Truesteel Ingots with the Draenor profession cooldown and/or Forge work orders, and obtain ten Sorcerous Fire. Keep the soulbound ingots on the character crafting the pet.\n\n4. Have a Blacksmith Hammer or equivalent crafting tool available, craft Soul of the Forge and use the resulting item. A non-blacksmith's Forge can help generate materials but does not offer the pet as an NPC craft; buy a cage if you want to avoid changing professions.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=84853",
    },
    [1570] = {
