        },
        npcId = 88367,
        petNPCID = 88367,
        name = "Sunfire Kaliri",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A level 3 Garrison, Menagerie upgrades, a developed battle team and repeated random daily bags are needed from scratch.\n\n1. Upgrade your Garrison to level 3 and learn Battle Pet Training. Accept Unearthed Magic from Lio the Lioness (Alliance) or Serr'ah (Horde), collect the Strange Stone near the mine entrance and return it. Its Ultimate Battle-Training Stone can create your first level-25 pet.\n\n2. Accept Pets Versus Pests and defeat Carrotus Maximus, Gorefu and Gnawface. Bring Aquatic attacks for the Elemental carrot, Flying attacks for the Aquatic Gorefu and Beast attacks for the Critter rat. A rare level-25 Ikky can use Black Claw followed by Flock against each, with healthy backups. Turn in the quest to open the Menagerie.\n\n3. Buy and build the Menagerie upgrades through the Architect Table. Earn Draenic Pet Battler for the level 3 blueprint; the current requirement is 150 pet battles in Draenor, not the original 500. Keep battling ordinary wild pets while collecting the Draenor Safari species, then finish the level 3 construction.\n\n4. Accept the available account-wide Menagerie daily before fighting: Battle Pet Roundup at Lunarfall or Scrappin' at Frostwall. Inspect today's opponents, choose family counters and time dodges for large attacks. Win the full battle and turn in the daily at your level 3 Menagerie.\n\n5. Open Big Bag of Pet Supplies (118697) for a chance at Sunfire Kaliri. Other Menagerie pets or no pet are possible. Learn the item if it appears; otherwise repeat after the daily reset or buy this exact species as a cage. The same account-wide daily is not a new bag on every alt.",
