    },
    [1571] = {
        category = "Reputation",
        source = "Steamwheedle Preservation Society - Revered",
        itemId = 119148,
        description = "Earn the named reputation on the purchasing character, save the Apexis/gold price, then buy the companion.",
        difficulty = "medium",
        difficultyReason = "Simple legacy combat, but reputation and currency collection require a sustained route.",
        requirements = "Steamwheedle Preservation Society - Revered",
        cost = "2,000 Apexis Crystals plus 1,000 gold base price, reduced by applicable reputation discounts",
        commentIDs = { 2008914 },
        tips = "A learned pet cage bypasses the vendor's reputation and purchasing-faction requirements. Draenor Timewalking commendations, when available from the current event vendor, can supplement the grind; check the actual faction token rather than buying a similarly named Outland token.",
        waypoints = {
            {
                mapID = 550,
                x = 0.502,
                y = 0.41200000000000003,
                step = 2,
                label = "Preservation Society - relic/fragment hand-ins",
            },
            { mapID = 550, x = 0.504, y = 0.414, step = 4, label = "Kwilax Fuseshiv - Albino River Calf vendor" },
            { mapID = 550, x = 0.516, y = 0.162, step = 2, label = "Aogexon - reputation trophy chance" },
            { mapID = 550, x = 0.341, y = 0.515, step = 2, label = "Mu'gra - reputation trophy chance" },
            {
                mapID = 550,
                x = 0.37200000000000005,
                y = 0.38799999999999996,
                step = 2,
                label = "Vileclaw - reputation trophy chance",
            },
        },
        npcId = 85281,
        petNPCID = 85281,
        name = "Albino River Calf",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use either faction and check its Steamwheedle Preservation Society reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Farm eligible wildlife and Highmaul Reliquary chests in northern Draenor Nagrand for Gorian Artifact Fragments and Highmaul Relics. Bring batches of twenty fragments or individual relics to Sallee Silverclamp at Ruins of Na'gwa 50.2,41.2 for 250 / 350 base reputation. Turn the named rare beasts' trophy items in to Gazmolf for 500 base reputation each. Continue until Revered.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Buy Indentured Albino River Calf from Kwilax Fuseshiv at Ruins of Na'gwa 50.4,41.4, or Gazrix Gearlock in Stormshield / Mimi Wizzlebub in Warspear. This white calf is a different species from River Calf, Sea Calf and Periwinkle Calf.\n\n5. Use the purchased item to learn Albino River Calf. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=85281",
        references = {
            "https://www.wowhead.com/npc=85281",
            "https://www.wowhead.com/item=119148",
            "https://www.wowhead.com/npc=85281#comments:id=2008914",
        },
    },
    [1572] = {
        category = "Pet Battles",
        source = "Wild capture - Talador, including the country around Vol'jin's Pride",
        description = "Capture Brilliant Bloodfeather in a wild pet battle. Search the documented habitat for a green paw, rather than attacking ordinary critters with character abilities.",
        difficulty = "easy",
        difficultyReason = "A normal level-23 to level-25 wild capture with a prepared team.",
        requirements = "Battle Pet Training, a usable trap and a healthy team suited to Draenor's level-23 to level-25 wild pets",
        cost = "No currency; these wild captures cannot be caged",
        commentIDs = { 2063243 },
        tips = "Take any quality for collection credit and upgrade it with a battle-stone later. Clear nearby hostile creatures before starting, stand on unobstructed ground and heal between attempts. Old random-group realm hopping is not a reliable Retail method.",
        waypoints = {
            {
                mapID = 535,
                x = 0.72,
                y = 0.22,
                step = 2,
                label = "Northern Talador - Bloodfeather search / Kelp Scuttler backlines",
            },
        },
        npcId = 88385,
        petNPCID = 88385,
        name = "Brilliant Bloodfeather",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A normal level-23 to level-25 wild capture with a prepared team.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to Talador, including the country around Vol'jin's Pride. Search the woodland and grass around the northern Talador settlements. Local Bloodfeather battles around 72,22 can also supply Kelp Scuttlers in the backline. Confirm Brilliant Bloodfeather rather than the similar Golden Dawnfeather from Spires.\n\n3. Engage the green-paw pet and check the enemy names. If Brilliant Bloodfeather is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Brilliant Bloodfeather below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=88385",
        references = { "https://www.wowhead.com/npc=88385", "https://www.wowhead.com/npc=88385#comments:id=2063243" },
    },
    [1573] = {
        category = "Pet Battles",
        source = "Wild capture - the forests around Southport and Axefall, Spires of Arak",
        description = "Capture Golden Dawnfeather in a wild pet battle. Search the documented habitat for a green paw, rather than attacking ordinary critters with character abilities.",
        difficulty = "medium",
        difficultyReason = "Limited primary spawns, phasing or an uncommon backline can extend the search.",
        requirements = "Battle Pet Training, a usable trap and a healthy team suited to Draenor's level-23 to level-25 wild pets",
        cost = "No currency; these wild captures cannot be caged",
        commentIDs = { 2046506, 2055435, 2184112, 2497897 },
