        name = "Golden Dawnfeather",
        warlordsPetGuide = true,
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Limited primary spawns, phasing or an uncommon backline can extend the search.\n\n1. Enable Track Pets and prepare a level-25 capture team. Terrible Turnip's Weakening Blow or a similar attack that cannot kill the target helps avoid accidental deaths; keep two healthy pets to finish the encounter.\n\n2. Travel to the forests around Southport and Axefall, Spires of Arak. Check 44,61 and 58,68. The small birds without a green paw are ordinary critters. Some outpost boundaries phase primaries out: use another spawn away from the boundary. Its Love Potion heals it; reduce its health again before trapping rather than assuming the old health total still applies.\n\n3. Engage the green-paw pet and check the enemy names. If Golden Dawnfeather is in a secondary slot, defeat the pet ahead of it. Avoid strong damage-over-time effects and multi-round attacks as the desired pet approaches capture health.\n\n4. Lower Golden Dawnfeather below 35% health and use Trap until it succeeds. Win the remaining battle to keep the capture. You can trap only one opponent per battle, so choose this species before catching a different backline pet.",
