        npcId = 88401,
        petNPCID = 88401,
        name = "Son of Sethe",
        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use either faction and check its Arakkoa Outcasts reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Complete the Spires of Arak story quests that award Arakkoa Outcasts reputation. Continue with eligible enemies in Skettis or Lost Veil Anzu if needed. Use the reputation panel to confirm Revered before traveling to the quartermaster.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Buy Son of Sethe from Shadow-Sage Brakoss in Stormshield 44.5,75.0 (Alliance) or Ravenspeaker Skeega in Warspear 53.4,59.8 (Horde). Both serve the same Arakkoa Outcasts faction.\n\n5. Use the purchased item to learn Son of Sethe. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
        wowheadUrl = "https://www.wowhead.com/npc=88401",
        references = {
            "https://www.wowhead.com/npc=88401",
            "https://www.wowhead.com/item=119143",
            "https://www.wowhead.com/npc=88401#comments:id=2063301",
        },
    },
    [1575] = {
