        warlordsPetGuide = true,
        sourceType = "Reputation",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Simple legacy combat, but reputation and currency collection require a sustained route.\n\n1. For the direct purchase, use an Alliance character and check its Sha'tari Defense reputation. If you only want the companion, compare its Auction House cage price before starting the faction grind.\n\n2. Build and upgrade the Trading Post to level 2 in Lunarfall to unlock Sha'tari Defense reputation. Kill eligible enemies in Shattrath City's hostile districts and harbor until Revered; Rune Ritualists around 36.7,44.7 are a useful elite cluster. Check that the first kills increase reputation, and deal character damage yourself if pet-only kills give none. This is the Draenor faction, not Outland's Sha'tari Skyguard.\n\n3. Save two thousand Apexis Crystals from Draenor assault quests, eligible missions or other Draenor rewards, plus the vendor's displayed gold cost. Gold discounts do not reduce the two-thousand-crystal requirement.\n\n4. Buy Sky Fry from Maaria at the level 2-or-higher Trading Post in Lunarfall. Its movable plot is why the pin marks a Garrison reference. The pet may learn at uncommon quality; that is still the correct collectible.\n\n5. Use the purchased item to learn Sky Fry. If using the alternative cage, confirm the species name and that its level does not exceed the highest pet level your account can learn. Buying a cage does not require earning the vendor reputation first.",
        reviewedAt = "2026-11-14",
