        petNPCID = 88490,
        name = "Eye of Observation",
        warlordsPetGuide = true,
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Hard - The five-rune summon needs coordination and the pet is not a guaranteed drop.\n\n1. Go to Orumo the Observer near 31.4,47.6 in Talador. The Pet Journal historically misspelled the source as Oromu/Oromo; Orumo is the rare NPC you need, not the little Eye of Observation companion.\n\n2. Bring five players and put one player on each small rune directly in front of the rare. Activate them together so Orumo emerges from the shadow realm and becomes attackable. Clearing random surrounding mobs does not replace the rune interaction.\n\n3. Ensure everyone has an eligible tag, defeat Orumo and loot the corpse. The Eye is a chance, not a guaranteed drop for every party member.\n\n4. Learn the Eye if awarded. If another attempt is needed, return with eligible characters after the loot reset, or buy the cage. Use the displayed loot eligibility rather than assuming that every immediate repeat kill gives another pet roll.",
        reviewedAt = "2026-11-14",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=88490",
        references = {
            "https://www.wowhead.com/npc=88490",
            "https://www.wowhead.com/npc=88490#comments:id=2037796",
            "https://www.wowhead.com/npc=88490#comments:id=2040640",
        },
    },
