        acquisition = "Difficulty: Medium - A level-25 trainer victory is needed before the simple gold purchase.\n\n1. Travel to Vesharr at Veil Terokk, Spires of Arak 46.2,45.4. Bring a healthy level-25 team. Arakkoa Outcasts reputation can discount the price but does not replace the required trainer victory.\n\n2. Defeat his complete pet team. Use Magic attacks against the Flying Darkwing / Great Kaliri and Elemental attacks against the Mechanical Apexis Guardian. Keep a defensive or healthy backup pet; do not waste a major attack into an active avoidance move.\n\n3. Speak to Vesharr again after the win and open his wares. Buy Veilwatcher Hatchling for its base 1000 gold price, reduced by any displayed discount. Veilwatcher and Kaliri Hatchling are separate purchases.\n\n4. Use the pet item to learn it. If you leave the purchase for another day, expect to beat him again to reopen the stock. A purchased cage bypasses the battle and vendor requirements.",
