            ["Data/Expansions/WarlordsOfDraenor/PetGuides.lua"] = "-- Hand-authored Retail guides for the 124 pets already in the Draenor catalog.\n-- Wowhead parent comments and replies were read interactively, 2026-11-14.\n-- Historical beta sources, obsolete realm hopping and profit steps are omitted.",
        },
    },
})

--[====[
Preserved inactive research: Data/Expansions/WarlordsOfDraenor/PetQuestRoutes.lua
This material is retained for reference and does not register character quest routes.

-- Character quest flags drive the next destination through the existing
-- event-driven quest-progress engine. Reference pins remain independent.
local _,TDP=...
local guides=TDP.CollectionWalkthroughs.pets
local routes=TDP.CollectionQuestRoutes
local sources=TDP.CollectionSourceIndex.quests
local function point(map,x,y) return {mapID=map,x=x/100,y=y/100} end
local function copy(value)
    if type(value)~="table" then return value end
    local result={}
    for k,v in pairs(value) do result[k]=copy(v) end
    return result
end
local function quest(id,name,instructions,options)
    local s=sources[id] or {}
    local q={questID=id,name=name,instructions=instructions,requires=copy(s.sourceQuests or {}),
        requiredCount=s.sqreq,faction=s.faction,npcID=s.qgs and s.qgs[1],
        sourceURL="https://www.wowhead.com/quest="..id,turnInReference=true,objectiveReference=true}
    local loc=s.coords and s.coords[1]
    if loc then q.pickup=point(loc[1],loc[2],loc[3]) end
    for k,v in pairs(options or {}) do q[k]=v end
    return q
end
local function attach(ids,route)
    route.version,route.reviewedAt=1,"2026-11-14"
    routes[route.key]=route
    for _,id in ipairs(ids) do
        local guide=guides[id]
        guide.questRoutes=guide.questRoutes or {}
        guide.questRoutes[#guide.questRoutes+1]=route
        guide.keepReferencePins,guide.separateQuestMap=true,true
    end
end

