        {35488,35762,"Death to the Dreadmaul","Kill eight Dreadmaul ogres. Collect the named-target and poisoning tasks before clearing their camp."},
        {35495,35760,"Toothsmash the Annihilator","Find and defeat Toothsmash at the marked Dreadmaul camp. Ordinary ogre kills do not replace this named enemy."},
